class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> values = new HashSet<>();
        for (int num : nums) {
            values.add(num);
        }

        int best = 0;
        for (int num : values) {
            if (values.contains(num - 1)) {
                continue;
            }

            int current = num;
            int length = 1;
            while (values.contains(current + 1)) {
                current++;
                length++;
            }
            best = Math.max(best, length);
        }
        return best;
    }
}

class Solution {
    public int longestConsecutive(int[] nums) {
        Map<Integer, Integer> lengthByBoundary = new HashMap<>();
        int best = 0;

        for (int num : nums) {
            if (lengthByBoundary.containsKey(num)) {
                continue;
            }

            int leftLength = lengthByBoundary.getOrDefault(num - 1, 0);
            int rightLength = lengthByBoundary.getOrDefault(num + 1, 0);
            int mergedLength = leftLength + 1 + rightLength;

            lengthByBoundary.put(num, mergedLength);
            lengthByBoundary.put(num - leftLength, mergedLength);
            lengthByBoundary.put(num + rightLength, mergedLength);
            best = Math.max(best, mergedLength);
        }

        return best;
    }
}

class Solution {
    public int longestConsecutive(int[] nums) {
        Set<Integer> remaining = new HashSet<>();
        for (int num : nums) {
            remaining.add(num);
        }

        int best = 0;
        while (!remaining.isEmpty()) {
            int start = remaining.iterator().next();
            remaining.remove(start);

            int length = 1;
            int left = start - 1;
            while (remaining.remove(left)) {
                left--;
                length++;
            }

            int right = start + 1;
            while (remaining.remove(right)) {
                right++;
                length++;
            }

            best = Math.max(best, length);
        }
        return best;
    }
}
